import test from "node:test";import assert from "node:assert/strict";
import {MarketIntegrityGateway} from "../gateway.mjs";import {MemoryDecisionLedger} from "../ledger.mjs";import {fixture} from "./fixture.mjs";import {verifyDecisionReceipt} from "../receipt.mjs";
const now=Date.parse("2026-10-12T12:00:00Z"),f=fixture(),ledger=new MemoryDecisionLedger(),keys=await crypto.subtle.generateKey({name:"ECDSA",namedCurve:"P-256"},false,["sign","verify"]),spki=Buffer.from(await crypto.subtle.exportKey("spki",keys.publicKey)).toString("base64url");const execution={address:f.intent.account,network:{chainId:f.intent.chainId},payload:{quantity:"99"},requestId:"fixture"};const gateway=new MarketIntegrityGateway({authenticate:async req=>req,decodeExecution:async e=>({...f.intent,quantityBaseUnits:e.payload.quantity}),loadApprovedPolicy:async()=>({...f.policy,approvalReference:"fixture-committee"}),loadCanonical:async()=>structuredClone(f.state),ledgerFor:()=>ledger,signer:keys.privateKey,keyId:"fixture",verifyAuthority:{keys:[{keyId:"fixture",spki}],maxTtlSeconds:60},ttlSeconds:60,clock:()=>now,revalidate:async()=>true});const principal={verified:true,account:f.intent.account,chainId:f.intent.chainId};
test("gateway authenticates canonical owner, ignores client classification, signs exact execution and consumes once",async()=>{const wrong=await gateway.authorize({...principal,verified:false},execution,"bad");assert.equal(wrong.receipt,null);const result=await gateway.authorize(principal,execution,"one");assert.equal(result.decision.executionAllowed,true);assert.equal((await verifyDecisionReceipt(result.receipt,execution,{keys:[{keyId:"fixture",spki}],maxTtlSeconds:60},now)).account,principal.account);const consumed=await gateway.consume(principal,execution,result.receipt);assert.equal(consumed.payload.status,"CONSUMED");await assert.rejects(()=>gateway.consume(principal,execution,result.receipt));await assert.rejects(()=>gateway.consume({...principal,account:"other"},execution,result.receipt));});
